"use client";
/**
 * Concentric Radius: set the outer radius and the gap, and the inner radius
 * follows so nested corners share one centre (inner = outer − gap). The
 * wrapper publishes all three as CSS variables for anything nested inside.
 */
import type { CSSProperties, ElementType, ReactNode } from "react";

/** The radius that keeps a nested corner concentric with its parent. */
export const innerRadius = (outer: number, gap: number) => Math.max(0, outer - gap);

/** CSS variables for a nested pair: `--radius-outer`, `--radius-gap`, `--radius-inner`. */
export function concentricVars(outer: number, gap: number): CSSProperties {
  return { "--radius-outer": `${outer}px`, "--radius-gap": `${gap}px`, "--radius-inner": `${innerRadius(outer, gap)}px` } as CSSProperties;
}

export interface ConcentricProps {
  /** Outer corner radius in pixels. */
  radius: number;
  /** Space between the outer edge and what it holds, in pixels. */
  gap: number;
  as?: ElementType;
  className?: string;
  style?: CSSProperties;
  children?: ReactNode;
}

/**
 * A surface that pads its content by `gap` and rounds its corners by `radius`.
 * Give nested surfaces `border-radius: var(--radius-inner)`, or use `Concentric.Inner`.
 */
export function Concentric({ radius, gap, as: Tag = "div", className, style, children }: ConcentricProps) {
  return (
    <Tag className={className} style={{ ...concentricVars(radius, gap), borderRadius: radius, padding: gap, ...style }}>
      {children}
    </Tag>
  );
}

function Inner({ as: Tag = "div", className, style, children }: Omit<ConcentricProps, "radius" | "gap">) {
  return (
    <Tag className={className} style={{ borderRadius: "var(--radius-inner)", ...style }}>
      {children}
    </Tag>
  );
}

Concentric.Inner = Inner;
